head.script:
scwin.onLoadComplete = function() {
    scwin.$w.executeSubmission("submission1");
};
scwin.submission1_submitdone = function(e) {
    // scwin.setGridViewGroupBy1();
    // scwin.setGridViewGroupBy2();
};
scwin.countFormatFunction = function(value) {
    return "총판매수량 : " + value + " 개 ";
};
scwin.sumFormatFunction = function(value) {
    return "총판매액 : " + value + " 원 ";
};
scwin.gridView1_ongroupby = function(options) {
    var sDate = new Date();
    // options.hideHeader = true;		// [true | false] 상단 숨김 여부 default:false.
    // options.hideFooter = true;		// [true | false] 하단 숨김 여부 default:false.
    options.closeGroup = false;
    // options.sortIndex = ["branch"];
    // options.sortOrder = ["1"];
    options.rowNumHeader = {
        colSpan: "6",
        inputType: "expression",
        expression: "toggle() + depthStr() + ' [ ' + count() + ' 건 ] '",
        align: "left"
    };
    options.rowNumFooter = {
        colSpan: "4"
    };
    options.groupbyFooter = [{
        inputType: "expression",
        expression: "SUM('sale_number')",
        displayFormatter: "scwin.countFormatFunction",
        align: "center"
    }, {
        inputType: "expression",
        expression: "SUM('sale_price')",
        displayFormatter: "scwin.sumFormatFunction",
        align: "center"
    }];
    gridView1.groupby(options);
    var eDate = new Date();
    txt1.setValue("1. options.closeGroup = false;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;duration[" + (eDate - sDate) + "ms]");
};
scwin.gridView2_ongroupby = function(options) {
    var sDate = new Date();
    // options.hideHeader = true;		// [true | false] 상단 숨김 여부 default:false.
    // options.hideFooter = true;		// [true | false] 하단 숨김 여부 default:false.
    options.closeGroup = true;
    // options.sortIndex = ["branch"];
    // options.sortOrder = ["1"];
    options.rowNumHeader = {
        colSpan: "6",
        inputType: "expression",
        expression: "toggle() + depthStr() + ' [ ' + count() + ' 건 ] '",
        align: "left"
    };
    options.rowNumFooter = {
        colSpan: "4"
    };
    options.groupbyFooter = [{
        inputType: "expression",
        expression: "SUM('sale_number')",
        displayFormatter: "scwin.countFormatFunction",
        align: "center"
    }, {
        inputType: "expression",
        expression: "SUM('sale_price')",
        displayFormatter: "scwin.sumFormatFunction",
        align: "center"
    }];
    gridView2.groupby(options);
    var eDate = new Date();
    txt2.setValue("2. options.closeGroup = true;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;duration[" + (eDate - sDate) + "ms]");
};
scwin.simulateWrapper = function(target, type, options) {
    WebSquare.wUnit.getJq(target).simulate(type, options);
}
scwin.getTime = function() {
    var time = WebSquare.wUnit.getJq(".w2textbox")[2].innerText;
    time = time.slice(time.indexOf("[") + 1, time.indexOf("ms]"));
    return parseInt(time, 10) < 500 ? true : false;
}
scwin.setSimulate1 = function() {
    scwin.simulateWrapper('#gridView1_column9', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.setSimulate2 = function() {
    scwin.simulateWrapper('#gridView2_column9', 'drag-n-drop', {
        dx: 0,
        dy: -60
    });
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 상단의 그리드(options.closeGroup = false; 일경우)와 하단의 그리드(options.closeGroup = true; 일경우) 대리점항목명을 마우스로 드래그하여 위로 끌어다 놓는다. 
    //1. Run the sample file and drag it to the top grid (if options.closeGroup = false;) and the bottom grid (if options.closeGroup = true;
    //Verify step 1. The upper grid and the lower grid are grouped by the agency name and the time (duration 370 ms) is shown.
    WebSquare.wUnit.addCommand("pause", "800");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate1()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column').length == 1", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value').text() == '대리점'", "true");
    WebSquare.wUnit.addCommand("set", "scwin.setSimulate2()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column:last').length == 1", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_groupbyZone_column_value:last').text() == '대리점'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.getTime()", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    scwin.onLoadComplete();
    //Function 
    //Created by: Thuyet.Pham
    //Created date: 26-Apr-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
